const signupFormSection = document.querySelector('.section-signup-form');
const signinFormSection = document.querySelector('.section-signin-form');

function showSection(sectionToShow, sectionToHide) {
    sectionToHide.classList.replace('display-on', 'display-off');
    sectionToShow.classList.replace('display-off', 'display-on');
}

document.querySelector('.signup-image-link').addEventListener('click', (event) => {
    event.preventDefault();
    showSection(signupFormSection, signinFormSection);
});

document.querySelector('.signin-image-link').addEventListener('click', (event) => {
    event.preventDefault();
    showSection(signinFormSection, signupFormSection);
});

document.querySelector('#register-form').addEventListener('submit', (event) => {
    event.preventDefault();
    const form = event.target;

    if (form.elements.pass.value !== form.elements.re_pass.value) {
        alertDialog('FAILED!', 'Passwords do not match');
        return;
    }

    submitForm(form, 'register.php');
});

document.querySelector('#login-form').addEventListener('submit', (event) => {
    event.preventDefault();
    submitForm(event.target, 'login.php');
});

/**
 * Sends the form and goes to the timeline when the server accepts it.
 */
async function submitForm(form, url) {
    const submitButton = form.querySelector('[type=submit]');
    submitButton.disabled = true;

    const data = await postJson(url, formToObject(form));

    if (data.code === 0) {
        window.location.href = 'home.php';
    } else {
        alertDialog(data.title, data.message);
        submitButton.disabled = false;
    }
}
